function round2(x){ return Math.round((x+Number.EPSILON)*100)/100; }
function compound(principal, rate, years, opts){
  opts=opts||{};
  var n=opts.frequency||1;
  principal=Number(principal); rate=Number(rate); years=Number(years);
  if(isNaN(principal) || !(principal>=0)) return {error:'principal invalid'};
  if(isNaN(rate) || isNaN(years) || years<=0) return {error:'rate/years invalid'};
  var fv = principal*Math.pow(1+rate/n, n*years);
  return {futureValue:fv, principal:principal, interest:fv-principal, rate:rate, years:years, frequency:n, error:null};
}
function amortize(principal, annualRate, years, opts){
  opts=opts||{};
  principal=Number(principal); annualRate=Number(annualRate); years=Number(years);
  if(isNaN(principal) || !(principal>0)) return {error:'principal must be > 0'};
  if(isNaN(years) || years<=0) return {error:'years must be > 0'};
  var n=Math.round(years*12);
  var r=annualRate/12;
  var payment;
  if(r===0){ payment=principal/n; }
  else { payment=principal*r/(1-Math.pow(1+r,-n)); }
  var balance=principal, schedule=[], totalInterest=0;
  for(var m=1;m<=n;m++){
    var interestPaid = balance*r;
    var principalPaid = payment - interestPaid;
    balance -= principalPaid;
    if(m===n){ principalPaid += balance; balance=0; }
    totalInterest += interestPaid;
    schedule.push({month:m, payment:round2(payment), principalPaid:round2(principalPaid), interestPaid:round2(interestPaid), balance:round2(Math.max(balance,0))});
  }
  return {monthlyPayment:round2(payment), totalPayment:round2(payment*n), totalInterest:round2(totalInterest), schedule:schedule, error:null};
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { compound:compound, amortize:amortize };
}
if (typeof window !== 'undefined') {
  window.InterestForgePure = { compound:compound, amortize:amortize };
}
